108: // AuthStyle is a copy of the golang.org/x/oauth2 package's AuthStyle type.
109: type AuthStyle int
110: 
111: const (
112: 	AuthStyleUnknown  AuthStyle = 0
113: 	AuthStyleInParams AuthStyle = 1
114: 	AuthStyleInHeader AuthStyle = 2
115: )
